-- Headroom in the 15 v1-global-fallback cells on the replay day (Figma K2, 20 Nov 00:00-24:00, no sampling): max DI ST / LT count
-- per changed cell (non-List-A/B/C sessions), and the Dict 1 Desktop fires (ST count > 7.49). Run 2026-11-25, Snowflake (database_id 14).
WITH s0 AS (SELECT session_ts ts, di_dictionary_num_matched_at_session_created d, os_at_session_created os, COALESCE(webgl_unmasked_renderer_at_session_created,'') r, COALESCE(cdn__ja4_hash_at_session_created,'') ja4, COALESCE(ua_at_session_created,'') ua, latest_risk_band rb, sessions_verified ver, was_challenged chl, sessions_solved sol, di_short_term_count_at_session_created stc, di_long_term_count_at_session_created ltc, LEFT(MD5(di_matched_signature_at_session_created),10) sig, di_matched_signature_at_session_created ms, user_ip_at_session_created ip FROM ARK_PROD.STARFLEET.PROD_INT_SESSION_SUMMARY WHERE public_key='A207F8A1-ED09-4325-ACE6-C8E26A458FBA' AND session_last_timestamp>='2026-11-20' AND session_last_timestamp<'2026-11-21 06:00' AND session_ts>='2026-11-20' AND session_ts<'2026-11-21' AND di_dictionary_num_matched_at_session_created IS NOT NULL),
s1 AS (SELECT s0.*, CASE WHEN r ILIKE '%SwiftShader%' OR r ILIKE '%llvmpipe%' OR r ILIKE '%VirtualBox%' OR r ILIKE '%VMware%' THEN 'A' WHEN r ILIKE '%Basic Render Driver%' AND COALESCE(os,'')<>'Windows' THEN 'B' WHEN COALESCE(os,'') IN ('','--') AND r<>'' THEN 'B' WHEN ja4 LIKE 't%' AND SPLIT_PART(ja4,'_',2) IN ('a09f3c656075','2802a3db6c62') AND os IN ('Windows','GNU/Linux','Ubuntu','Chrome OS') THEN 'C' WHEN ua LIKE '%Chrome/%' AND RIGHT(SPLIT_PART(ja4,'_',1),2)='h1' THEN 'C' WHEN TRY_TO_NUMBER(REGEXP_SUBSTR(ua,'Chrome/([0-9]+)',1,1,'e',1))>=70 AND ja4 LIKE 't12%' THEN 'C' END AS x, CASE WHEN r ILIKE '%Basic Render Driver%' AND os='Windows' THEN 'WinRDVM' WHEN os IN ('Windows','OS X','Chrome OS') THEN 'Desktop' WHEN os IN ('iOS','iPadOS','Android') THEN 'Mobile' WHEN os IN ('GNU/Linux','Ubuntu') THEN 'Linux' ELSE 'Other' END AS grp FROM s0)
SELECT 'CELL|'||d||'|'||grp||'|n='||COUNT(*)||'|stc_max='||MAX(stc)||'|ltc_max='||MAX(ltc) x FROM s1 WHERE x IS NULL AND (d IN (-1,1) OR grp='Other') GROUP BY d,grp
UNION ALL SELECT 'FIRE|'||TO_CHAR(ts,'HH24:MI:SS')||'|'||sig||'|'||ms||'|stc='||stc||'|ltc='||ltc||'|'||COALESCE(rb,'-')||'|ver='||ver||'|chl='||chl||'|sol='||COALESCE(sol,0)||'|'||COALESCE(ip,'')||'|'||ja4||'|'||ua x FROM s1 WHERE x IS NULL AND d=1 AND grp='Desktop' AND stc>7.49
ORDER BY 1;
